PREFIX afiliaciones: <https://w3id.org/rastro/afiliaciones#>
SELECT (COUNT(DISTINCT ?m) AS ?n) WHERE {
  ?m a afiliaciones:AffiliationMention ;
     afiliaciones:affiliationText ?t .
  FILTER(CONTAINS(LCASE(STR(?t)), "argentin"))
  FILTER NOT EXISTS {
    ?i a afiliaciones:Identification ;
       afiliaciones:ofMention ?m ;
       afiliaciones:identifies ?o .
  }
}
